from django.utils.translation import get_language

def plan_message(code):
    kk=(get_language() or '').startswith('kk')
    messages={
        'not_floor_plan':('Планировка не распознана. Загрузите план этажа или чёткое фото самого чертежа, где видны комнаты. Фото помещения и фасады не подходят. Можно ввести данные вручную.','Жоспар анықталмады. Қабат жоспарын немесе бөлмелері көрінетін сызбаның анық фотосын жүктеңіз. Бөлме фотосы мен қасбет жарамайды. Деректерді қолмен енгізуге болады.'),
        'animated_image':('Выберите один неподвижный кадр плана: JPG, PNG или WEBP.','Жоспардың бір қозғалмайтын суретін таңдаңыз: JPG, PNG немесе WEBP.'),
        'pdf_complexity':('PDF слишком сложный для анализа. Сохраните только нужные страницы как простой PDF или чёткие изображения.','PDF талдау үшін тым күрделі. Тек қажет беттерді қарапайым PDF не анық сурет ретінде сақтаңыз.'),
        'pixel_limit':('Выберите изображение плана не более 20 Мп.','Көлемі 20 Мп-ден аспайтын жоспар суретін таңдаңыз.'),
        'running':('Анализ ещё выполняется. Обновите страницу позже; повторно загружать файл не нужно.','Талдау жүріп жатыр. Бетті кейін жаңартыңыз; файлды қайта жүктеу қажет емес.'),
        'no_rooms':('Не удалось уверенно выделить помещения. Добавьте комнаты вручную по сохранённому плану.','Бөлмелерді сенімді анықтау мүмкін болмады. Сақталған жоспар бойынша бөлмелерді қолмен қосыңыз.'),
        'not_configured':('Файл сохранён. Автоматический анализ сейчас недоступен. Введите площадь вручную или откройте готовый пример.','Файл сақталды. Автоматты талдау қазір қолжетімсіз. Ауданды қолмен енгізіңіз немесе дайын мысалды ашыңыз.'),
        'budget_limit':('Лимит пилота не позволяет новый анализ. Сохранённые результаты и ручные правки доступны.','Пилот лимиті жаңа талдауға жетпейді. Сақталған нәтижелер мен қолмен түзету қолжетімді.'),
        'duplicate_call':('Этот файл уже отправлялся. Повторный платный запрос заблокирован; откройте сохранённый результат.','Бұл файл бұрын жіберілген. Қайта ақылы сұрау бұғатталды; сақталған нәтижені ашыңыз.'),
        'legacy_analysis':('Для файла есть результат старого формата. Автоматическая повторная оплата запрещена. Используйте ручное уточнение.','Файлдың ескі пішімдегі нәтижесі бар. Автоматты қайта төлеуге тыйым салынған. Қолмен нақтылаңыз.'),
        'page_limit':('Нужен PDF от 1 до 12 страниц без пароля. Выберите страницы планировки.','Құпиясөзсіз 1–12 беттік PDF қажет. Жоспар беттерін таңдаңыз.'),
        'file_limit':('Для автоматического анализа выберите файл до 5 МБ.','Автоматты талдау үшін көлемі 5 МБ-ға дейінгі файлды таңдаңыз.'),
        'unreadable_file':('Не удалось прочитать план. Попробуйте чёткое фото сверху или укажите данные вручную.','Жоспар оқылмады. Жоғарыдан анық түсірілген суретті қолданыңыз немесе деректерді қолмен енгізіңіз.'),
    }
    return messages.get(str(code),('Не удалось завершить анализ. Автоматического повтора и повторной оплаты не будет. Можно уточнить данные вручную.','Талдау аяқталмады. Автоматты қайталау және қайта төлеу болмайды. Деректерді қолмен нақтылауға болады.'))[1 if kk else 0]
